void OAIDeprecatedApi::replaceAsset(const QString &id, const OAIHttpFileElement &asset_data, const QString &device_asset_id, const QString &device_id, const QDateTime &file_created_at, const QDateTime &file_modified_at, const ::OpenAPI::OptionalParam<QString> &key, const ::OpenAPI::OptionalParam<QString> &slug, const ::OpenAPI::OptionalParam<QString> &duration, const ::OpenAPI::OptionalParam<QString> &filename) {
    QString fullPath = QString(_serverConfigs["replaceAsset"][_serverIndices.value("replaceAsset")].URL()+"/assets/{id}/original");
    
    if (_apiKeys.contains("api_key")) {
        addHeaders("api_key",_apiKeys.find("api_key").value());
    }
    
    if (!_bearerToken.isEmpty())
        addHeaders("Authorization", "Bearer " + _bearerToken);
    
    
    {
        QString idPathParam("{");
        idPathParam.append("id").append("}");
        QString pathPrefix, pathSuffix, pathDelimiter;
        QString pathStyle = "simple";
        if (pathStyle == "")
            pathStyle = "simple";
        pathPrefix = getParamStylePrefix(pathStyle);
        pathSuffix = getParamStyleSuffix(pathStyle);
        pathDelimiter = getParamStyleDelimiter(pathStyle, "id", false);
        QString paramString = (pathStyle == "matrix") ? pathPrefix+"id"+pathSuffix : pathPrefix;
        fullPath.replace(idPathParam, paramString+QUrl::toPercentEncoding(::OpenAPI::toStringValue(id)));
    }
    QString queryPrefix, querySuffix, queryDelimiter, queryStyle;
    if (key.hasValue())
    {
        queryStyle = "form";
        if (queryStyle == "")
            queryStyle = "form";
        queryPrefix = getParamStylePrefix(queryStyle);
        querySuffix = getParamStyleSuffix(queryStyle);
        queryDelimiter = getParamStyleDelimiter(queryStyle, "key", true);
        if (fullPath.indexOf("?") > 0)
            fullPath.append(queryPrefix);
        else
            fullPath.append("?");

        fullPath.append(QUrl::toPercentEncoding("key")).append(querySuffix).append(QUrl::toPercentEncoding(::OpenAPI::toStringValue(key.stringValue())));
    }
    if (slug.hasValue())
    {
        queryStyle = "form";
        if (queryStyle == "")
            queryStyle = "form";
        queryPrefix = getParamStylePrefix(queryStyle);
        querySuffix = getParamStyleSuffix(queryStyle);
        queryDelimiter = getParamStyleDelimiter(queryStyle, "slug", true);
        if (fullPath.indexOf("?") > 0)
            fullPath.append(queryPrefix);
        else
            fullPath.append("?");

        fullPath.append(QUrl::toPercentEncoding("slug")).append(querySuffix).append(QUrl::toPercentEncoding(::OpenAPI::toStringValue(slug.stringValue())));
    }
    OAIHttpRequestWorker *worker = new OAIHttpRequestWorker(this, _manager);
    worker->setTimeOut(_timeOut);
    worker->setWorkingDirectory(_workingDirectory);
    OAIHttpRequestInput input(fullPath, "PUT");

    
    {
        input.add_file("assetData", asset_data.local_filename, asset_data.request_filename, asset_data.mime_type);
    }
    
    {
        input.add_var("deviceAssetId", ::OpenAPI::toStringValue(device_asset_id));
    }
    
    {
        input.add_var("deviceId", ::OpenAPI::toStringValue(device_id));
    }
    if (duration.hasValue())
    {
        input.add_var("duration", ::OpenAPI::toStringValue(duration.value()));
    }
    
    {
        input.add_var("fileCreatedAt", ::OpenAPI::toStringValue(file_created_at));
    }
    
    {
        input.add_var("fileModifiedAt", ::OpenAPI::toStringValue(file_modified_at));
    }
    if (filename.hasValue())
    {
        input.add_var("filename", ::OpenAPI::toStringValue(filename.value()));
    }

    for (auto it = _defaultHeaders.constBegin(); it != _defaultHeaders.constEnd(); ++it) {
        input.headers.insert(it.key(), it.value());
    }


    connect(worker, &OAIHttpRequestWorker::on_execution_finished, this, &OAIDeprecatedApi::replaceAssetCallback);
    connect(this, &OAIDeprecatedApi::abortRequestsSignal, worker, &QObject::deleteLater);
    connect(worker, &QObject::destroyed, this, [this] {
        if (findChildren<OAIHttpRequestWorker*>().count() == 0) {
            Q_EMIT allPendingRequestsCompleted();
        }
    });

    worker->execute(&input);
}

